import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { TinyUrl, CreateUrlDto } from '../models/tiny-url.model';
import { environment } from '../../environments/environment';

@Injectable({
  providedIn: 'root'
})
export class TinyUrlService {
  private baseUrl = environment.apiUrl;

  constructor(private http: HttpClient) {}

  // POST /api/add → create short URL
  createUrl(dto: CreateUrlDto): Observable<TinyUrl> {
    return this.http.post<TinyUrl>(`${this.baseUrl}/api/add`, dto);
  }

  // GET /api/public → list all public URLs
  getPublicUrls(): Observable<TinyUrl[]> {
    return this.http.get<TinyUrl[]>(`${this.baseUrl}/api/public`);
  }

  // DELETE /api/delete/{code} → delete specific URL
  deleteUrl(code: string): Observable<any> {
    return this.http.delete(`${this.baseUrl}/api/delete/${code}`);
  }

  // PUT /api/update/{code} → update URL
  updateUrl(code: string, dto: Partial<CreateUrlDto>): Observable<TinyUrl> {
    return this.http.put<TinyUrl>(`${this.baseUrl}/api/update/${code}`, dto);
  }
}
